edits.after:
.component-main>.editor-icon:first-child{color:var(--accent);justify-self:center}.component-main>.editor-icon:last-child{justify-self:center}.compound-shapes article header>label{min-width:0;display:flex;align-items:center;gap:var(--ui-control-gap);font-size:var(--type-body);line-height:var(--line-body)}.compound-shapes article header>select{width:100%;min-width:0}
@container nova-compound (max-width:22em){.compound-shapes article header{grid-template-columns:minmax(0,1fr)}.compound-shapes article header>.ui-button{inline-size:var(--ui-control-height);justify-self:end}}
@container component-choice (max-width:22em){.component-main{grid-template-columns:var(--ui-icon-size) minmax(0,1fr);grid-template-rows:var(--ui-control-height) auto;column-gap:0;row-gap:var(--ui-control-gap);padding-inline:var(--space-4)}.component-main>.editor-icon:first-child{grid-column:1;grid-row:1}.component-main>.editor-icon:last-child{grid-column:2;grid-row:1;justify-self:start}.component-main>span:nth-child(2){grid-column:1/-1;grid-row:2}}

function startEdit(entity: Entity) {
  if (!canEdit.value || entity.editorLocked) return
  const index = hierarchyRows.value.findIndex(row => row.entity.id === entity.id), list = entityList.value
  if (list && index >= 0) {
    const top = hierarchyContentInset.value + index * hierarchyRowHeight.value, bottom = top + hierarchyRowHeight.value
    if (top < list.scrollTop) list.scrollTop = top
    else if (bottom > list.scrollTop + list.clientHeight) list.scrollTop = bottom - list.clientHeight
    hierarchyScrollTop.value = list.scrollTop
  }
  editingId.value = entity.id; editName.value = entity.name
}
function cancelEdit() { editingId.value = null; editName.value = ''; editorState.renameRequestId = null }

/* Row-local rename geometry matches the exact virtual stride. */
.hierarchy-rows{padding-inline:var(--ui-panel-inset)}
.edit-input,.scene-main input{height:var(--ui-tree-row-height);min-height:0;min-width:0;max-width:100%;font-size:var(--type-body);line-height:var(--line-control);padding-inline:var(--space-3);padding-block:max(0px,calc((var(--ui-tree-row-height) - var(--type-body) * var(--line-control) - 2 * var(--ui-border-width)) / 2));border-width:var(--ui-border-width);border-radius:var(--radius-input)}.edit-input{width:100%}

.reroute-row>label{min-width:0;display:grid;gap:var(--ui-label-control-gap)}.reroute-row>label input,.number-metadata input,.variables article>div:first-child>input,.variables article>div:first-child>select{width:100%;min-width:0}.reroute-row>.ui-button,.variables article>div:first-child>.ui-button{grid-column:1/-1;inline-size:var(--ui-control-height);justify-self:end}
/* Diagram typography uses graph zoom; precise node/port/router coordinates stay local. */
.graph-transform :is(button,input,select){min-height:0;min-width:0}.graph-transform button{padding:0}.graph-transform .node-source button{padding:0 6px;min-height:25px}
